	// (GET /auth/2fa/recovery-codes)
	GetTotpRecoveryStatus(c *gin.Context)
	// GenerateTotpRecoveryCodes 生成/重置恢复码
	// (POST /auth/2fa/recovery-codes)
	GenerateTotpRecoveryCodes(c *gin.Context)
	// SetupTotp 生成 TOTP 密钥
	// (POST /auth/2fa/setup)
	SetupTotp(c *gin.Context)
